        cout<<"5 4 3 2 1"<<endl;
        }

            }
            int X;
             cin>>X;
            int sum;
             cin>> sum ;

    if (sum =+arr[n]> X){
        cout<<""<<endl;


    }
    cout<<""<<sum<<endl;










return 0;
}

