using namespace std;


int main(){
    int n;
    int x;
    int a[n];

    cin>>n;
    for(int i=0; i<=n; i++)
    {
        cin>>a[i];

    }
    int i;
    for(i=n;a[i]<n;--i)
    {
        cout<<a[n];

    }
    cin>>x;

    int sum;
    for(int j=0;j<n; j++)
    {
        if(x>a[j])
        sum=sum+a[j];
    }
    cout<<sum;

    return 0;
}

