#include<iostream>
using namespace std;
int main(){
    int n,x;
    bool elements(n)={};
    cin>>n>>elements(n)>>x;
    for (int j=0; j<=n;++j){
      bool reversed(n)={};
      reversed(j)=elements(n-j);
      cout>>reversed(j)>>endl;
    }
    for(int i=0;elements(i)>x;++i){
        int sum =0;
        sum+=elements(i);
        cout<<sum<<endl;
    }
    return 0;
}

