void rev(const vector<int>&arr,int x){
    int sum =0;
    for(int i :arr){
        if (i>x){sum+=i;
        }
    cout<<sum;
    return;
    }
}
int main (void){
    vector<int>arr;
    int n,x;
    cin>>n;
    for(int i=0;i<n;i++){
        int a;
        cin>>a;
        arr::push_back(a);
    }
    cin>>x;
    for(int i=0;i<n;i++){
        cout<<arr[n-i-1];
    }
    sum (arr, x)
}

