#include<iostream>
using namespace std;
void reverseArray(int array[] , int k){
    for(int i=k-1 ; i>=0 ; i--){
    cout<< array[i]<<" ";
}
}
void printSum( int arrayy[], int p, int y){
    for( int i=0; i<p ; i++){
    if ( arrayy[i]>y){
        int sum=0;
        sum=sum+arrayy[i];
        cout<<sum;
    }
}
}


