#include<iostream>
using namespace std;
int p(int n,int k){
    if(n-k+1<=1)return 1;
    if(n-2*k+1<=1)return 1;
    if(k<=1) return 1;
    if(n-k+1<k)return 0;
    return ((n-k+1)*p(n-k+1-1,k))/((((n-(2*k)+1)*p(n-(2*k)+1-1,k)))*(k*p(k-1,k)));
}
int main(){
   int n,k;
   cin>>n>>k;
   cout<<p(n,k);


}

