int B(const int &n,const int &k){
    if(n>3&&n-k==1){
        return false;
    }
    if(n==0&&n>=k){
        return false;
    }
    B(3,2)==1;
    B(2,1)==2;
    B(n,k)==B(n-1,k)+B(n-2,k-1);
    return B(n,k);
}

