int binary (int n , int k){



    if(n==2 && k==1) return 1;
    if(n==1 && k==1) return 1;
    else if(n<1) return 0;
    else if(n %2 != 0 && k >= n/2+1) return 1;
    if(k > n/2+1) return 0;





    return binary(n-1,k)+binary(n-2,k-2);

}
