#include<iostream>
using namespace std;

int Count(int digits, int num){
    if (digits == 0 ){
        return 0;
    }
    if (digits == 1 ){
        return 1;
    }
    if (digits == 2){
        return 2;
    }
    return Count (digits-1,num-1) + Count (digits-2,num-1);
}
int main(){
    int digit,sum;
    cin>> digit;
    cin>> sum;
    cout << Count (digit,sum);
}

