int B(int n, int k){
    if (k>n) return 0;
    if (k=n==0) return 0;
    if (k=n){
     return 1;
    }
    return (B(n-1,k) + B(n-2,k-1));


}

int main(){
    int n,k;
    cin>>n>>k;
    cout<<B(n,k);
}

#include<iostream>
#include<vector>

using namespace std;

int calcBS(int n, int k){
    //base case
   if(n <= k) return 0;
   if((n%2==1) && (n == (k + 1)) return 1;
    while(n>k){
    calcBS(n, k) = calcBS(n-1,k) + calcBS(n-2,k-1);
    }
    return calcBS;
}
 int main(){
    int n , k;
    cin >> n >> k ;
   if((n%2==1) && (n == (k + 1)) cout<< 1;


    return 0;
 }

