#include <iostream>
#include <vector>
using namespace std;

int binary (int n , int k){



    if(n==2 && k==1) return 1;
    if(n==1 && k==1) return 1;
    else if(n<1) return 0;
    else if(n %2 != 0 && k >= n/2+1) return 1;
    if(k > n/2+1) return 0;





    return binary(n-1,k)+binary(n-2,k-2);

}
int main(){
    int n ;
    int k;
    cin >> n;
    cin >> k;

    cout << binary(n,k);

}

#include <iostream>
using namespace std;

int fact(int n){
    int p=1;
    for (int i =0; i<=n;i++){
        p = p*i;
        }
    cout << p;
    return p;
}

int main(){
    float n;
    float k;
    cin >> n >> k;

    if (k>(n/2)+0.5 ){
     cout << "0";

     }

    else if (k==(n/2)+0.5 ){
     cout << "1";

    }

    else if (k==(n/2) && k!=2 && n!=4){
        cout << "2";

    }

    else if (k<(n/2)){
        float a = (fact(n)/(fact(k)*fact(n-k)))-(fact(n-1)/(fact(k-1)*fact(n-k-2)));
        cout << a;

     }

     else if ( k==2 && n==4){
        cout << "3";
     }
}

