#include <iostream>
using namespace std;

void bubblesort(int A[], int n) {
for(int i=0; i<n-1; i++) {
for(int j=0; j<n-i-1; j++) {
if(A[j] > A[j+1])
swap(A[j],A[j+1]);
}
}
}
int main(int A[], int n) {
    cin >> A[n]>> n;
bubblesort(A, n);
}

