#include <iostream>

using namespace std;

int k , n ;
cin >> k;
cin >> n;
int countstr(n,k){
    if (n == 0){
        return 0;
    }
    if (n == 1 ){
        return 1;
    }

    if (n%2 !=0 && k == ((n+1)/2)){
        return 1;
    }

    int oddcases = countstr(n-1,k);
    int evencases = countstr(n-2, k-1);
    return oddcases + evencases ;

}

