int fact(int a){
    if(a<=1) return 1;
    return a*fact(a-1);
}

int C(int n,int k){
    return fact(n)/(fact(k)*fact(n-k));
}
int countSequence(int n,int k){

    if(n==1 && k==1) return 1;
    if(k==1) return n;
    if(n==1) return 1;
    C(n, k) = C(n-1, k) + C(n, k-1);
    return C(n, k);
}
